383	// merged `list` calls: GET /clusters (the slug→host catalog used to synthesise
384	// clone URLs) and GET /repos?scope=all (the directory). It points the
385	// active-context client seam at the server for the test. Only the /repos
386	// request is delivered on the returned channel — receiving it after the command
387	// runs is the happens-before edge that synchronises handler-goroutine writes
388	// with test-goroutine reads (HTTP completion alone is not an edge the race
389	// detector recognises; see TestBearerOnlySource_NoCookieOnTheWire). Buffered so
390	// the handler never blocks on the send.
391	func serveRepoList(t *testing.T, repos []coreapi.RepoIndexEntry, clusters []coreapi.Cluster, truncated bool) <-chan recordedRequest {
392		t.Helper()
393		recCh := make(chan recordedRequest, 1)
394		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
395			w.Header().Set("Content-Type", "application/json")
